from __future__ import annotations
from itertools import product
from typing import Iterable

def words(alphabet: tuple[str, ...], n: int) -> Iterable[tuple[str, ...]]:
    for length in range(n + 1):
        yield from product(alphabet, repeat=length)

def memory(word: tuple[str, ...], modulus: int = 3) -> int:
    return len(word) % modulus

def first_collision(alphabet: tuple[str, ...], n: int) -> tuple[tuple[str, ...], tuple[str, ...], int] | None:
    seen: dict[int, tuple[str, ...]] = {}
    for word in words(alphabet, n):
        state = memory(word)
        if state in seen and seen[state] != word:
            return seen[state], word, state
        seen[state] = word
    return None

if __name__ == "__main__":
    print(first_collision(("a", "b"), 4))

from __future__ import annotations

def forget(word: str, retained: set[str]) -> str:
    return "".join(ch for ch in word if ch in retained)

def demonstrate() -> None:
    retained = {"a", "c"}
    samples = ["ac", "abc", "abbc", "bacb"]
    outputs = {word: forget(word, retained) for word in samples}
    assert len(set(outputs.values())) == 1
    for word, output in outputs.items():
        print(f"{word:5s} -> {output}")

if __name__ == "__main__":
    demonstrate()

